style.css:
/* Pas standaard checkboxes aan */
input[type="checkbox"] {
    width: 20px; /* Grootte aanpassen */
    height: 20px;
    background-color: #1a1a1a; /* Achtergrondkleur */
    border: 2px solid #ff0000; /* Rood randje */
    border-radius: 5px; /* Afgeronde hoeken */
    cursor: pointer;
}

/* Stijl voor aangevinkte checkboxes */
input[type="checkbox"]:checked {
    background-color: #00ff00; /* Groene achtergrond */
    border-color: #00cc00;
}

/* Voeg een vinkje toe */
input[type="checkbox"]:checked::before {
    content: "✔";
    color: white;
    font-size: 16px;
    position: absolute;
    left: 3px;
    top: -1px;
}
